<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__) . '/config/config.php';
require_sign_in();
$schools = []; $loadError = '';$editNotifications=[];$editNotificationCount=0;
if(in_array($_SESSION['role']??'', ['system_admin','sub_admin'],true)){try{$q=db()->query("SELECT r.id,r.school_id,r.proposed_name,r.created_at,s.name school_name,u.name requested_by_name FROM school_edit_requests r JOIN schools s ON s.id=r.school_id JOIN users u ON u.id=r.requested_by WHERE r.status='pending' ORDER BY r.created_at DESC");$editNotifications=$q->fetchAll();$editNotificationCount=count($editNotifications);}catch(Throwable $ignored){}}
if (can_manage_schools()) {
    try { $schools = db()->query('SELECT id, name, location, status FROM schools ORDER BY created_at DESC LIMIT 8')->fetchAll(); }
    catch (PDOException $e) { $loadError = 'School records are not available. Check the database connection and schema.'; }
}
$roleNames = ['system_admin'=>'System admin','sub_admin'=>'Sub admin','admin'=>'Admin','director'=>'Director','sub_director'=>'School manager','headteacher'=>'Head of school','head_academic'=>'Head of academics','assistant_academic'=>'Assistant academic','examination_officer'=>'Examination officer','teacher'=>'Teacher','driver'=>'Driver','hr'=>'HR','storekeeper'=>'Stores'];
$roleName = $roleNames[$_SESSION['role'] ?? ''] ?? 'School team';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f7f8f4"><title>Overview · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="workspace-label">WORKSPACE</div><nav class="side-nav" aria-label="Main navigation"><a class="nav-item active" href="index.php"><span class="nav-icon" aria-hidden="true">⌂</span>Overview</a><?php if(!in_array($_SESSION['role'],['headteacher','teacher'],true)):?><a class="nav-item" href="schools.php"><span class="nav-icon" aria-hidden="true">▦</span>Schools</a><?php endif;?><?php if($_SESSION['role']!=='teacher'):?><a class="nav-item" href="team.php"><span class="nav-icon" aria-hidden="true">♧</span>Team</a><?php endif;?><?php if(in_array($_SESSION['role'],['system_admin','sub_admin'],true)):?><a class="nav-item" href="audit.php"><span class="nav-icon" aria-hidden="true">◷</span>Audit log</a><?php endif;?><a class="nav-item" href="academics.php"><span class="nav-icon" aria-hidden="true">▤</span>Academics</a><a class="nav-item" href="notes.php"><span class="nav-icon" aria-hidden="true">▧</span>Learning notes</a><a class="nav-item disabled" href="#" aria-disabled="true" title="Available as your workspace grows"><span class="nav-icon" aria-hidden="true">◷</span>Subscriptions</a><?php if(in_array($_SESSION['role']??'', ['system_admin','sub_admin'],true)):?><a class="nav-item" href="requests.php">✉ &nbsp;Requests<?php $requestBadgeCount=pending_school_edit_request_count();if($requestBadgeCount):?><span class="side-nav-count"><?=$requestBadgeCount>99?'99+':$requestBadgeCount?></span><?php endif;?></a><?php endif;?></nav><div class="sidebar-bottom"><div class="help-box"><span class="help-mark">?</span><strong>Need a hand?</strong><p>Your school workspace is just getting started.</p></div><a class="nav-item" href="logout.php"><span class="nav-icon" aria-hidden="true">↪</span>Sign out</a></div></aside><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Workspace <span>/</span> Overview</div><?php if(in_array($_SESSION['role']??'', ['system_admin','sub_admin'],true)):$pendingEditCount=pending_school_edit_request_count();?><a class="notification-bell" href="requests.php#requested" aria-label="<?=$pendingEditCount?> pending edit requests" title="<?=$pendingEditCount?> pending edit requests"><span aria-hidden="true">🔔</span><?php if($pendingEditCount):?><span class="notification-badge"><?=$pendingEditCount>99?'99+':$pendingEditCount?></span><?php endif;?></a><?php endif;?><div class="top-actions"><span class="role-chip"><?=e($roleName)?></span><div class="user-avatar" aria-hidden="true"><?=e(strtoupper(substr($_SESSION['name'] ?? 'U',0,1)))?></div><div class="user-name"><?=e($_SESSION['name'] ?? 'User')?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">YOUR SCHOOL NETWORK</div><h1>Good day, <?=e(explode(' ', trim($_SESSION['name'] ?? 'there'))[0])?>.</h1><p class="muted">Here’s the latest across your workspace.</p></div><?php if (can_manage_schools()): ?><a class="button primary" href="#schools">View schools <span aria-hidden="true">→</span></a><?php endif; ?></section><?php if($editNotificationCount):?><section class="content-section school-edit-notifications" aria-label="Notifications"><div class="section-heading"><div><div class="eyebrow">NOTIFICATIONS</div><h2>School edit requests</h2><p class="muted"><?=$editNotificationCount?> request<?=($editNotificationCount===1?'':'s')?> need review.</p></div><span class="count-pill"><?=$editNotificationCount?> pending</span></div><div class="school-notification-list"><?php foreach(array_slice($editNotifications,0,5) as $notification):?><a class="school-notification" href="school_edit_review.php?id=<?=$notification['school_id']?>"><span class="school-notification-icon" aria-hidden="true">✎</span><span><strong><?=e($notification['school_name'])?> · <?=e($notification['proposed_name'])?></strong><small>Requested by <?=e($notification['requested_by_name'])?> · <?=e(date('j M Y H:i',strtotime($notification['created_at'])))?></small></span><span class="school-notification-action">Review →</span></a><?php endforeach;?></div></section><?php endif;?><?php if (can_manage_schools()): ?><section class="metric-grid" aria-label="School overview"><article class="metric-card"><div class="metric-label">SCHOOLS IN NETWORK</div><div class="metric-value"><?=count($schools)?></div><div class="metric-note">Registered schools</div><span class="metric-symbol mint" aria-hidden="true">▦</span></article><article class="metric-card"><div class="metric-label">YOUR ROLE</div><div class="metric-value metric-role"><?=e($roleName)?></div><div class="metric-note">Access level</div><span class="metric-symbol lilac" aria-hidden="true">◇</span></article><article class="metric-card"><div class="metric-label">WORKSPACE</div><div class="metric-value metric-role">ShuleLite</div><div class="metric-note">School operations</div><span class="metric-symbol peach" aria-hidden="true">✳</span></article></section><?php endif; ?><section class="content-section" id="schools"><div class="section-heading"><div><div class="eyebrow">NETWORK</div><h2>Schools</h2></div><?php if (can_manage_schools()): ?><span class="count-pill"><?=count($schools)?> schools</span><?php endif; ?></div><?php if (!can_manage_schools()): ?><div class="empty-state"><span class="empty-icon" aria-hidden="true">⌂</span><h3>Your workspace is ready</h3><p>Your school information and tasks will appear here when they’re set up.</p></div><?php elseif ($loadError): ?><div class="notice error" role="alert"><?=e($loadError)?></div><?php elseif (!$schools): ?><div class="empty-state"><span class="empty-icon" aria-hidden="true">▦</span><h3>No schools added yet</h3><p>School records will appear here once your network is set up.</p><span class="empty-hint">Ask a director or administrator to register the first school.</span></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>School</th><th>Location</th><th>Status</th></tr></thead><tbody><?php foreach ($schools as $school): ?><tr><td class="school-cell"><span class="school-avatar"><?=e(strtoupper(substr($school['name'],0,1)))?></span><?=e($school['name'])?></td><td><?=e($school['location'] ?: '—')?></td><td><span class="status-badge <?=e($school['status'])?>"><span></span><?=e(ucfirst($school['status']))?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><footer class="page-footer">ShuleLite <span>·</span> A calmer way to run a school day.</footer></div></main></div></body></html>
